    total = sum((Decimal(re.sub(r'[^0-9.]', '', r['amount'])) for r in inputs['confirmed']), Decimal('0'))
    problems = []
    if f'${total:,.2f}' != out['logged_total']:
        problems.append(f"total {out['logged_total']} differs from the confirmed rows ({total})")
    required = {r['sender'] for r in inputs['to_return']} | {'ap-lead@company.example.com'}
    if required != set(out['sent']) | set(out['send_errors']):
        problems.append('not every required email is accounted for')
    return {'status': 'fail' if problems else 'pass', 'reason': '; '.join(problems) or 'Total and emails are consistent.', 'evidence': []}


